<template><div class="auth"><h1>登录 Light</h1><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" placeholder="用户名" /></el-form-item><el-form-item><el-input v-model="form.password" type="password" placeholder="密码" show-password /></el-form-item><el-button type="primary" native-type="submit" :loading="loading">登录</el-button><el-link @click="$router.push('/register')">注册账号</el-link></el-form></div></template>
<script setup lang="ts">import { reactive, ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { identityApi } from '@/api';const router=useRouter();const loading=ref(false);const form=reactive({username:'',password:''});async function submit(){loading.value=true;try{const r=await identityApi.login(form);localStorage.setItem('light_access_token',r.data.accessToken);localStorage.setItem('light_refresh_token',r.data.refreshToken);router.push('/')}catch(e){ElMessage.error('登录失败')}finally{loading.value=false}}</script>
<style scoped>.auth{max-width:380px;margin:15vh auto;padding:32px;background:white;border-radius:16px}.auth h1{margin-bottom:24px}.el-button{width:100%;margin-bottom:16px}</style>
